=== src/invoice.js
     1	const { subtotal } = require('./order');
     2	const { tax } = require('./tax');
     3	// Invoices are legal documents: each line shown here must reconcile with the totals.
     4	function invoice(order) {
     5	  const sub = subtotal(order); const t = tax(order);
     6	  return { lines: order.lines, subtotalCents: sub, taxCents: t, totalCents: sub + t };
     7	}
     8	module.exports = { invoice };
=== src/order.js
     1	// An order is a list of lines; amounts are in cents.
     2	function subtotal(order) { return order.lines.reduce((s, l) => s + l.unitCents * l.qty, 0); }
     3	module.exports = { subtotal };
=== src/refund.js
     1	const { RATE } = require('./tax');
     2	// Refund one order line: the line's price plus the VAT charged on it.
     3	function refundLine(order, lineIndex, qty) {
     4	  const line = order.lines[lineIndex];
     5	  if (qty > line.qty) throw new Error('cannot refund more than was bought');
     6	  const net = line.unitCents * qty;
     7	  return net + Math.round(net * RATE);
     8	}
     9	module.exports = { refundLine };
=== src/tax.js
     1	const { subtotal } = require('./order');
     2	const RATE = 0.2; // VAT, charged on the order subtotal
     3	function tax(order) { return Math.round(subtotal(order) * RATE); }
     4	module.exports = { tax, RATE };
=== test/shop.test.js
     1	const test = require('node:test'); const assert = require('node:assert');
     2	const { invoice } = require('../src/invoice');
     3	const { refundLine } = require('../src/refund');
     4	const order = { lines: [{ sku: 'a', unitCents: 1000, qty: 2 }, { sku: 'b', unitCents: 500, qty: 1 }] };
     5	test('invoice totals reconcile', () => { const i = invoice(order); assert.strictEqual(i.totalCents, i.subtotalCents + i.taxCents); assert.strictEqual(i.totalCents, 3000); });
     6	test('refund includes VAT on the line', () => assert.strictEqual(refundLine(order, 0, 1), 1200));

